questionvariables.text:
mn   : rand([[2,1],[3,1],[3,2],[4,1],[4,2],[4,3]]);
m    : mn[1];
nn   : mn[2];
sa   : m^2 - nn^2;        /* leg a = BC, opposite A */
sb   : 2*m*nn;            /* leg b = CA, opposite B */
sc   : m^2 + nn^2;        /* hypotenuse c = AB */
ssemi: (sa + sb + sc)/2;  /* semi-perimeter */
area : sa*sb/2;           /* area = half product of legs */
rin  : area/ssemi;        /* inradius = n(m-nn) = (a+b-c)/2 */
dia  : 2*rin;             /* diameter (a common slip) */
ta1  : rin;
